-- Checks of a norm project written by mantle.compliance.NormProjectServices.create#NormProject. Read only.
-- Parameter :project = workEffortId of the project (WetProject). Rows "check: ..." must be 0.
SELECT 'milestones' CHECK_NAME, COUNT(*) N FROM WORK_EFFORT WHERE ROOT_WORK_EFFORT_ID = ':project' AND WORK_EFFORT_TYPE_ENUM_ID = 'WetMilestone'
UNION ALL SELECT 'tasks', COUNT(*) FROM WORK_EFFORT WHERE ROOT_WORK_EFFORT_ID = ':project' AND WORK_EFFORT_TYPE_ENUM_ID = 'WetTask'
UNION ALL SELECT 'requirements ' || r.STATUS_ID, COUNT(*) FROM REQUIREMENT r JOIN WORK_REQUIREMENT_FULFILLMENT f ON f.REQUIREMENT_ID = r.REQUIREMENT_ID
    JOIN WORK_EFFORT w ON w.WORK_EFFORT_ID = f.WORK_EFFORT_ID WHERE w.ROOT_WORK_EFFORT_ID = ':project' GROUP BY r.STATUS_ID
UNION ALL SELECT 'check: tasks without requirement', COUNT(*) FROM WORK_EFFORT w WHERE w.ROOT_WORK_EFFORT_ID = ':project'
    AND w.WORK_EFFORT_TYPE_ENUM_ID = 'WetTask' AND NOT EXISTS (SELECT 1 FROM WORK_REQUIREMENT_FULFILLMENT f WHERE f.WORK_EFFORT_ID = w.WORK_EFFORT_ID)
UNION ALL SELECT 'check: requirements without their norm item', COUNT(*) FROM REQUIREMENT r JOIN WORK_REQUIREMENT_FULFILLMENT f ON f.REQUIREMENT_ID = r.REQUIREMENT_ID
    JOIN WORK_EFFORT w ON w.WORK_EFFORT_ID = f.WORK_EFFORT_ID LEFT JOIN AGREEMENT_ITEM i ON i.AGREEMENT_ID = r.AGREEMENT_ID
    AND i.AGREEMENT_ITEM_SEQ_ID = r.AGREEMENT_ITEM_SEQ_ID WHERE w.ROOT_WORK_EFFORT_ID = ':project' AND i.AGREEMENT_ID IS NULL
UNION ALL SELECT 'check: requirements twice for one product and item', COUNT(*) FROM (SELECT r.PRODUCT_ID, r.AGREEMENT_ID, r.AGREEMENT_ITEM_SEQ_ID
    FROM REQUIREMENT r JOIN WORK_REQUIREMENT_FULFILLMENT f ON f.REQUIREMENT_ID = r.REQUIREMENT_ID JOIN WORK_EFFORT w ON w.WORK_EFFORT_ID = f.WORK_EFFORT_ID
    WHERE w.ROOT_WORK_EFFORT_ID = ':project' AND r.STATUS_ID <> 'RqmtStRejected' GROUP BY r.PRODUCT_ID, r.AGREEMENT_ID, r.AGREEMENT_ITEM_SEQ_ID HAVING COUNT(*) > 1) d
UNION ALL SELECT 'check: open tasks of rejected requirements', COUNT(*) FROM REQUIREMENT r JOIN WORK_REQUIREMENT_FULFILLMENT f ON f.REQUIREMENT_ID = r.REQUIREMENT_ID
    JOIN WORK_EFFORT w ON w.WORK_EFFORT_ID = f.WORK_EFFORT_ID WHERE w.ROOT_WORK_EFFORT_ID = ':project' AND r.STATUS_ID = 'RqmtStRejected' AND w.STATUS_ID <> 'WeCancelled'
